"""Returns the list of pairs that you can create from the sequence. The results
    are ordered and no duplicates will be included, also, if <a,b> is in the result
    then <b,a> won't be."""
def pairs(sequence: Any) -> object {
    sequence = sorted(`list(`set(sequence)));
    indices = `list(range(len(sequence)));
    return [
        (sequence[i], sequence[j]) for i in indices
        for j in indices
        if (i < j)
    ];
}

""":yaql:single

    Checks that collection has only one element and returns it. If the
    collection is empty or has more than one element, raises StopIteration.

    :signature: collection.single()
    :receiverArg collection: input collection
    :argType collection: iterable
    :returnType: type of collection's elements

    .. code::

        yaql> ["abc"].single()
        "abc"
        yaql> [1, 2].single()
        Execution exception: Collection contains more than one item
    """
def single(collection: Any) -> object {
    it = iter(collection);
    result = next(it);
    try {
        next(it);
    } except StopIteration {
        return result;
    }
    raise StopIteration('Collection contains more than one item');
}

